#!/usr/bin/env python3
"""KATA WEBs: four independent editorial demo sites, and case-study portafolio.
Usage: python3 site/kata/build.py /path/to/deployment/root
Original media from the existing Vercel deployment must be present under /ej/{sector}/photo-*.webp.
No real forms, bookings, payments, companies, patient data or user testimonials.
"""
from pathlib import Path
import html, json, re, sys
ROOT = Path(sys.argv[1]).resolve()
OUT = ROOT / "ej"
def write(path, text):
    file = ROOT / path
    file.parent.mkdir(parents=True,exist_ok=True)
    file.write_text(text,encoding="utf8")
    print(path, len(text))

