def document(kind,inner,title,description,sub=False):
    d=config[kind];path=f"/ej/{kind}/";pref="../" if sub else ""
    meta=f'<meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><meta name="theme-color" content="{("#752e25" if kind=="taqueria" else "#193741" if kind=="plumber" else "#dee7db" if kind=="dentist" else "#111310")}">'
    font=f'<link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family={fonts[kind]}&display=swap" rel="stylesheet">'
    menu={
    "taqueria":[("La carta",path+"carta/"),("La cocina",path+"#cocina"),("Visítanos",path+"#visita")],
    "plumber":[("Trabajos",path+"#trabajos"),("Método",path+"#metodo"),("Zonas",path+"#zonas")],
    "dentist":[("Tratamientos",path+"#tratamientos"),("La experiencia",path+"#experiencia"),("Dudas",path+"#faq")],
    "barber":[("Servicios",path+"#servicios"),("El club",path+"#club"),("Galería",path+"#galeria")],
    }[kind]
    nav="".join(f'<a href="{href}">{txt}</a>' for txt,href in menu)
    header=f'<div class="demo-label"><span>CONCEPTO DE KATA WEBs · NEGOCIO FICTICIO</span><a href="/web/ejemplos/">Volver al portafolio</a></div><a class="skip" href="#main">Saltar al contenido</a><header class="site-nav"><a class="brand" href="{path}">{d["brand"]}</a><nav aria-label="Navegación principal">{nav}</nav><a class="nav-cta" href="{path+d["sub"]+"/"}">{d["subname"]} <span aria-hidden="true">↗</span></a></header>'
    footer=f'<footer><div><a class="brand" href="{path}">{d["brand"]}</a><p>Demostración de identidad y experiencia web. Negocio ficticio, sin servicios ni citas reales.</p></div><div><span>Explora</span><a href="{path}">Inicio</a><a href="{path+d["sub"]+"/"}">{d["subname"]}</a></div><div><span>Proyecto</span><a href="{path}credits.txt">Créditos fotográficos</a><a href="/web/ejemplos/">KATA WEBs</a></div></footer>'
    sticky=f'<div class="mobile-bar"><a href="{path+d["sub"]+"/"}">{d["cta"]} <span aria-hidden="true">↗</span></a></div>'
    return f'<!doctype html><html lang="es"><head>{meta}<title>{html.escape(title)}</title><meta name="description" content="{html.escape(description,quote=True)}">{font}<link rel="stylesheet" href="{pref}assets/new.css"></head><body class="{d["theme"]}">{header}<main id="main">{inner}</main>{footer}{sticky}<script src="{pref}assets/new.js" defer></script></body></html>'

